function renderSectionTitle(title, ac, bgMid) {
  var sz = window._sz;
  var mb = window._forExport ? '8px' : '1%';
  var pb = window._forExport ? '5px' : '1%';
  var isCursive = ['Dancing Script'].indexOf(customize.displayFont) >= 0;
  // Cursive fonts look broken in uppercase with letter-spacing
  // Use title case and remove letter-spacing for them
  var textTransform = isCursive ? 'none' : 'uppercase';
  var letterSpacing = isCursive ? '0.5px' : '2.5px';
  var displayTitle = isCursive ? toTitleCase(title) : title;
  var fontWeight = isCursive ? '700' : '600';
  return '<div class="pv-sec-title" style="font-family:\'' + customize.displayFont + '\',serif;font-size:' + sz.secTitle + ';color:' + ac + ';border-bottom:1px solid ' + bgMid + '55;margin-bottom:' + mb + ';padding-bottom:' + pb + ';text-transform:' + textTransform + ';letter-spacing:' + letterSpacing + ';font-weight:' + fontWeight + '">' + displayTitle + '</div>';
}

function toTitleCase(str) {
  return str.replace(/\w\S*/g, function(word) {
    return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
  });
}

function renderFieldRow(label, value, ac, bgMid) {
  if (!value) return '';
  var sz = window._sz;
  var mb = window._forExport ? '5px' : '1px';
  // Fixed label column width so long labels wrap within their own space
  // instead of overlapping the value. Wider label column on export.
  var labelWidth = window._forExport ? '115px' : '30%';
  return '<div class="pv-field" style="font-size:' + sz.field + ';line-height:1.5;margin-bottom:' + mb + '">' +
    '<span class="pv-field-label" style="color:' + darken(ac, 0.3) + ';font-size:' + sz.fieldLabel + ';width:' + labelWidth + '">' + label + ':</span>' +
    '<span class="pv-field-value" style="color:' + darken(ac, 0.15) + '">' + value + '</span></div>';
}

