// ===== COLOR HELPERS =====
function hexToLight(hex) {
  var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return 'rgb(' + Math.round(r + (255-r)*0.92) + ',' + Math.round(g + (255-g)*0.92) + ',' + Math.round(b + (255-b)*0.92) + ')';
}
function hexToMid(hex) {
  var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return 'rgb(' + Math.round(r + (255-r)*0.65) + ',' + Math.round(g + (255-g)*0.65) + ',' + Math.round(b + (255-b)*0.65) + ')';
}
function adjustBrightness(hex, amt) {
  var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  return 'rgb(' + Math.min(255,r+amt) + ',' + Math.min(255,g+amt) + ',' + Math.min(255,b+amt) + ')';
}
function darken(hex, factor) {
  var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  var f = 1 - factor;
  return 'rgb(' + Math.round(r + (40-r)*f) + ',' + Math.round(g + (20-g)*f) + ',' + Math.round(b + (10-b)*f) + ')';
}

function formatDate(dateStr) {
  var d = new Date(dateStr);
  var months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  var day = d.getDate();
  var suffix = day === 1 || day === 21 || day === 31 ? 'st' : day === 2 || day === 22 ? 'nd' : day === 3 || day === 23 ? 'rd' : 'th';
  return day + suffix + ' ' + months[d.getMonth()] + ', ' + d.getFullYear();
}

// ===== MOBILE PREVIEW =====
function openMobilePreview() {
  document.getElementById('mobile-preview-overlay').classList.add('open');
  document.body.style.overflow = 'hidden';
  // Render immediately (real file) — force a render even if debounce pending
  renderRealPreview();
}
function closeMobilePreview() {
  document.getElementById('mobile-preview-overlay').classList.remove('open');
  document.body.style.overflow = '';
}

// ===== EXPORT / IMPORT =====
function exportData() {
  readForm();
  var data = {
    version: 1,
    exportedAt: new Date().toISOString(),
    appName: 'MarriageBiodataCreator',
    formData: formData,
    siblings: siblings,
    hiddenFields: hiddenFields,
    hiddenSections: hiddenSections,
    customize: customize
  };
  var blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = 'biodata-data.json';
  a.click();
  URL.revokeObjectURL(url);
}

function importData() {
  document.getElementById('import-input').click();
}

function handleImport(e) {
  var file = e.target.files[0];
  if (!file) return;
  var reader = new FileReader();
  reader.onload = function(ev) {
    try {
      var data = JSON.parse(ev.target.result);
      if (data.formData) {
        formData = data.formData;
        Object.keys(formData).forEach(function(key) {
          var input = document.querySelector('.field-input[data-field="' + key + '"]');
          if (input) input.value = formData[key] || '';
        });
      }
      if (data.siblings) { siblings = data.siblings; renderSiblings(); }
      if (data.hiddenFields) {
        hiddenFields = data.hiddenFields;
        Object.keys(hiddenFields).forEach(function(f) {
          var btn = document.querySelector('.field-hide-btn[data-field="' + f + '"]');
          if (btn && hiddenFields[f]) { btn.textContent = 'Show'; btn.classList.add('hidden-field'); }
        });
      }
      if (data.hiddenSections) { hiddenSections = data.hiddenSections; }
      if (data.customize) {
        customize = Object.assign(customize, data.customize);
        var iconMig = {
          '\u0950': 'hinduism', '\u271D': 'christianity', '\u2720': 'christianity',
          '\u262A': 'islam', '\u262C': 'sikhism', '\u2638': 'none',
          '\u2721': 'none', '\u2625': 'none', '\u262F': 'none', '\u2605': 'none',
          '\u2767': 'none', '\u26E9': 'none', '\uFD3F': 'islam', '': 'none'
        };
        if (customize.icon && iconMig.hasOwnProperty(customize.icon)) {
          customize.icon = iconMig[customize.icon];
        }
        if (!iconOptions.find(function(ic) { return ic.id === customize.icon; })) {
          customize.icon = 'hinduism';
        }
        renderColorPresets();
        renderFontSelect();
        renderIconSelect();
      }
      updatePreview();
      alert('Data imported successfully!');
    } catch(err) {
      alert('Invalid file format. Please select a valid biodata JSON file.');
    }
  };
  reader.readAsText(file);
  e.target.value = '';
}

