var paymentDone = false;
// Clear any stale payment data on load
(function() {
  try { localStorage.removeItem('biodata_payment'); } catch(e) {}
})();
var generatedPDFBlob = null;
var generatedImageBlob = null;
var RAZORPAY_KEY = 'rzp_live_TSIjxHcMJly4MO'; // Replace with your Razorpay Key ID
var PAYMENT_AMOUNT = 9900; // ₹99 in paise

function isFreeTemplate() {
  return !!(currentTemplate && currentTemplate.free);
}

function updateDownloadButtons() {
  var free = isFreeTemplate();
  var pdfLabel = document.getElementById('btn-pdf-label');
  var imgLabel = document.getElementById('btn-img-label');
  if (pdfLabel) pdfLabel.textContent = free ? 'Download PDF — Free' : 'Download PDF — ₹99';
  if (imgLabel) imgLabel.textContent = free ? 'Download Image — Free' : 'Download Image — ₹99';
}

// ===== PAYMENT FLOW =====
function handleDownload(type) {
  // Free templates skip payment entirely
  if (isFreeTemplate() || paymentDone) {
    if (type === 'image') downloadImage();
    else downloadPDF();
    return;
  }
  // Store requested type so we can use it after payment
  window._downloadType = type || 'pdf';
  openPayment();
}

function confirmCloseSuccess() {
  var hasPDF = window._downloadedPDF;
  var hasImage = window._downloadedImage;

  if (hasPDF && hasImage) {
    // Both downloaded — close cleanly, no warning
    forceCloseSuccess();
    return;
  }

  // Build context-aware message
  var title, message;
  if (!hasPDF && !hasImage) {
    title = "Close without downloading?";
    message = "You haven't downloaded anything yet. If you close now, you'll need to pay again to download.";
  } else if (hasPDF && !hasImage) {
    title = "You've downloaded the PDF";
    message = "You can also download the Image at no extra charge. Close without it?";
  } else if (hasImage && !hasPDF) {
    title = "You've downloaded the Image";
    message = "You can also download the PDF at no extra charge. Close without it?";
  }

  document.getElementById('success-confirm-title').textContent = title;
  document.getElementById('success-confirm-msg').textContent = message;
  document.getElementById('success-confirm').style.display = 'flex';
}

function cancelCloseSuccess() {
  document.getElementById('success-confirm').style.display = 'none';
}

function forceCloseSuccess() {
  document.getElementById('success-confirm').style.display = 'none';
  document.getElementById('success-overlay').classList.remove('open');
  document.body.style.overflow = '';
  paymentDone = false;
  try { localStorage.removeItem('biodata_payment'); } catch(e) {}
}

function openPayment() {
  document.getElementById('payment-overlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closePayment(e) {
  if (e && e.target !== document.getElementById('payment-overlay') && !e.target.closest('.payment-close')) return;
  document.getElementById('payment-overlay').classList.remove('open');
  document.body.style.overflow = '';
}

// ===== PAYMENT CONFIG =====
// Replace these with your actual values after deploying the Cloudflare Worker
var WORKER_URL = 'https://marriage-biodata-payment-worker.marriagebiodatamaker.workers.dev';
var RAZORPAY_KEY_ID = 'rzp_test_TRwNu0u7XPgA0q'; // Test Key ID — replace with live key when Razorpay account is activated
var PAYMENT_AMOUNT = 9900; // ₹99 in paise

function initiatePayment() {
  closePayment();

  // Show loading state
  var loadingOverlay = document.createElement('div');
  loadingOverlay.id = 'payment-loading';
  loadingOverlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;display:flex;align-items:center;justify-content:center;font-family:Inter,sans-serif';
  loadingOverlay.innerHTML =
    '<div style="background:#fff;border-radius:16px;padding:32px;max-width:300px;width:90%;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,0.3)">' +
      '<div style="font-size:28px;margin-bottom:12px">💳</div>' +
      '<div style="font-size:15px;font-weight:600;color:#1a1a1a;margin-bottom:6px">Preparing payment...</div>' +
      '<div style="font-size:13px;color:#888">Please wait</div>' +
    '</div>';
  document.body.appendChild(loadingOverlay);

  // Step 1: Create order via Cloudflare Worker
  fetch(WORKER_URL + '/create-order', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ amount: PAYMENT_AMOUNT })
  })
  .then(function(res) { return res.json().then(function(data) { return { status: res.status, data: data }; }); })
  .then(function(result) {
    document.body.removeChild(loadingOverlay);
    console.log('Worker response:', result.status, result.data);

    if (!result.data.order_id) {
      alert('Could not initiate payment. Error: ' + (result.data.error || result.data.detail || JSON.stringify(result.data)) + '\n\nPlease try again or contact support.');
      return;
    }

    // Guard: ensure only ONE outcome is processed per checkout session
    var paymentOutcomeHandled = false;

    // Step 2: Open Razorpay checkout with the order
    var options = {
      key: RAZORPAY_KEY_ID,
      amount: result.data.amount,
      currency: result.data.currency,
      order_id: result.data.order_id,
      name: 'Marriage Biodata Maker',
      description: 'Biodata Download — PDF & Image',
      theme: { color: '#8B1A3A' },
      prefill: {
        name: formData.fullName || '',
        email: formData.email || '',
        contact: formData.phone || ''
      },
      handler: function(response) {
        // Success handler — only fires when Razorpay confirms payment captured.
        // Verify signature server-side before unlocking download.
        if (paymentOutcomeHandled) return;
        paymentOutcomeHandled = true;
        verifyAndActivate(response);
      },
      modal: {
        ondismiss: function() {
          // User closed checkout — reset so they can retry
          paymentOutcomeHandled = false;
        }
      }
    };

    try {
      var rzp = new Razorpay(options);
      rzp.on('payment.failed', function(response) {
        // Failure event — do NOT set paymentOutcomeHandled permanently,
        // because Razorpay allows retry in the same modal. Just show a toast.
        // Only show failure if the modal is actually closing (no retry).
        paymentDone = false;
        var reason = response.error ? (response.error.description || response.error.reason || 'Payment failed') : 'Payment failed';
        // Show a non-blocking inline message; user can still retry in the open modal
        console.log('Payment attempt failed:', reason);
      });
      rzp.open();
    } catch(e) {
      alert('Payment gateway could not load. Please disable any ad blockers and try again.');
    }
  })
  .catch(function() {
    if (document.getElementById('payment-loading')) {
      document.body.removeChild(loadingOverlay);
    }
    alert('Network error. Please check your connection and try again.');
  });
}

function verifyAndActivate(response) {
  // Show verifying state
  var verifyOverlay = document.createElement('div');
  verifyOverlay.id = 'payment-verifying';
  verifyOverlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;display:flex;align-items:center;justify-content:center;font-family:Inter,sans-serif';
  verifyOverlay.innerHTML =
    '<div style="background:#fff;border-radius:16px;padding:32px;max-width:300px;width:90%;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,0.3)">' +
      '<div style="font-size:28px;margin-bottom:12px">🔐</div>' +
      '<div style="font-size:15px;font-weight:600;color:#1a1a1a;margin-bottom:6px">Verifying payment...</div>' +
      '<div style="font-size:13px;color:#888">Please wait</div>' +
    '</div>';
  document.body.appendChild(verifyOverlay);

  function removeVerifyOverlay() {
    var el = document.getElementById('payment-verifying');
    if (el) el.parentNode.removeChild(el);
  }

  fetch(WORKER_URL + '/verify-payment', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      razorpay_order_id: response.razorpay_order_id,
      razorpay_payment_id: response.razorpay_payment_id,
      razorpay_signature: response.razorpay_signature
    })
  })
  .then(function(res) { return res.json(); })
  .then(function(data) {
    removeVerifyOverlay();
    if (data.success) {
      paymentDone = true;
      onPaymentSuccess();
    } else {
      showPaymentResult(false, 'Payment verification failed. Please contact support with Payment ID: ' + response.razorpay_payment_id);
    }
  })
  .catch(function(err) {
    removeVerifyOverlay();
    // Do NOT fall back to success on network error — show error instead
    showPaymentResult(false, 'Could not verify payment. Please contact support with Payment ID: ' + (response.razorpay_payment_id || 'unknown'));
  });
}

function showPaymentResult(success, message) {
  var overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:9999;display:flex;align-items:center;justify-content:center;font-family:Inter,sans-serif';
  overlay.innerHTML =
    '<div style="background:#fff;border-radius:16px;padding:32px;max-width:320px;width:90%;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,0.3)">' +
      '<div style="font-size:32px;margin-bottom:12px">' + (success ? '✅' : '❌') + '</div>' +
      '<div style="font-size:16px;font-weight:600;color:#1a1a1a;margin-bottom:8px">' + (success ? 'Payment Successful' : 'Payment Failed') + '</div>' +
      '<div style="font-size:13px;color:#888;margin-bottom:20px">' + (message || '') + '</div>' +
      '<button onclick="this.closest(\'div\').parentNode.remove()" style="padding:10px 24px;border:none;border-radius:10px;background:#8B1A3A;color:#fff;font-size:14px;font-weight:600;cursor:pointer">Close</button>' +
    '</div>';
  document.body.appendChild(overlay);
}

